package cl.bolsillo.app;
import org.json.*;import java.time.*;import java.util.*;
/** Additive local finance schema. A prior debt is not a bank transaction. */
final class Finance {
 /** Personal consumption excludes money advanced for others, independently of repayment timing. */
 static long personalExpense(JSONObject expense)throws Exception{long total=expense.getLong("amount"),shared=0;JSONArray parts=expense.optJSONArray("shares");if(parts!=null)for(int i=0;i<parts.length();i++)shared=Math.addExact(shared,parts.getJSONObject(i).getLong("amount"));return Math.max(0,total-shared);}
 static void migrate(JSONObject d)throws Exception{for(String key:new String[]{"people","planned","receivables","changeLog"})if(!d.has(key))d.put(key,new JSONArray());JSONArray prior=d.optJSONArray("receivables");if(prior!=null)for(int i=0;i<prior.length();i++){JSONObject debt=prior.getJSONObject(i);if(!debt.has("settled")||debt.isNull("settled"))debt.put("settled",0);}}
 static void validate(JSONObject d)throws Exception{
  for(String key:new String[]{"people","planned","receivables"}){JSONArray list=d.optJSONArray(key);if(list==null)continue;Ledger.require(list.length()<=1000,"Demasiados registros");Set<String> ids=new HashSet<>();for(int i=0;i<list.length();i++){JSONObject o=list.getJSONObject(i);Ledger.require(!o.optString("id").isEmpty()&&ids.add(o.getString("id"))&&!o.optString("name").trim().isEmpty(),"Revisa el nombre y el identificador");if(key.equals("planned")){Ledger.require(Ledger.money(o,"amount",false)>0,"Monto inválido");LocalDate.parse(o.getString("date"));Ledger.require(Ledger.find(d.getJSONArray("accounts"),o.getString("account"))!=null,"Cuenta inexistente");JSONObject cat=Ledger.find(d.getJSONArray("categories"),o.getString("category"));Ledger.require(cat!=null&&cat.optString("type").equals("expense"),"Categoría incompatible");Ledger.require(Arrays.asList("planned","paid","cancelled").contains(o.optString("status")),"Estado inválido");}if(key.equals("receivables")){long amount=Ledger.money(o,"amount",false),settled=Ledger.money(o,"settled",false);Ledger.require(amount>0&&settled<=amount,"Revisa el monto pendiente");Ledger.require(Ledger.find(d.getJSONArray("people"),o.optString("personId"))!=null,"Persona inexistente");Ledger.require(o.opt("loan") instanceof Boolean,"Tipo de deuda inválido");LocalDate.parse(o.getString("date"));Ledger.require(o.optString("note").length()<=300,"Detalle demasiado largo");}}}
  JSONArray debts=d.optJSONArray("receivables");if(debts!=null)for(int i=0;i<debts.length();i++){JSONObject debt=debts.getJSONObject(i);JSONArray history=debt.optJSONArray("settlementHistory");long sum=0;if(history!=null)for(int j=0;j<history.length();j++){JSONObject entry=history.getJSONObject(j);Ledger.require(Ledger.money(entry,"amount",false)>0,"Abono inválido");if(entry.has("extra"))Ledger.money(entry,"extra",false);LocalDate.parse(entry.getString("date"));Ledger.require(entry.optString("note").length()<=300,"Nota de abono demasiado larga");if(!entry.optBoolean("voided"))sum=Math.addExact(sum,entry.getLong("amount"));}Ledger.require(sum<=debt.optLong("settled"),"Los abonos superan lo saldado");}
 }
 static void validateShares(JSONObject d,JSONObject owner,boolean loan)throws Exception{JSONArray parts=owner.optJSONArray("shares");long total=0;Set<String> ids=new HashSet<>();if(parts!=null)for(int j=0;j<parts.length();j++){JSONObject s=parts.getJSONObject(j);Ledger.require(ids.add(s.getString("id"))&&Ledger.money(s,"amount",false)>0,"Revisa las partes del gasto");String person=s.optString("personId");Ledger.require(person.isEmpty()||Ledger.find(d.getJSONArray("people"),person)!=null,"Persona inexistente");total=Math.addExact(total,s.getLong("amount"));}Ledger.require(total<=owner.getLong("amount")&&(!loan||total==owner.getLong("amount")),"Las partes deben coincidir con el monto");}
 static long paid(JSONObject d,String key,boolean reserved)throws Exception{long sum=0;if(key.startsWith("prior:")){JSONObject prior=Ledger.find(d.getJSONArray("receivables"),key.substring(6));if(prior!=null)sum=prior.optLong("settled");}JSONArray tx=d.getJSONArray("transactions");for(int i=0;i<tx.length();i++){JSONObject t=tx.getJSONObject(i);if(t.optString("type").equals("repayment")&&t.optString("receivable").equals(key)&&(reserved||t.optString("status").equals("posted")&&t.getString("date").compareTo(Ledger.today())<=0))sum+=t.getLong("amount");}return sum;}
 static JSONArray claims(JSONObject d)throws Exception{return claims(d,false);}
 static JSONArray claims(JSONObject d,boolean includeClosed)throws Exception{Map<String,Long> posted=paymentsIndex(d,false),reserved=paymentsIndex(d,true);JSONArray out=new JSONArray(),prior=d.getJSONArray("receivables");for(int i=0;i<prior.length();i++){JSONObject p=prior.getJSONObject(i);String key="prior:"+p.getString("id");long left=p.getLong("amount")-posted.getOrDefault(key,0L);if(left>0||includeClosed)out.put(new JSONObject().put("key",key).put("personId",p.getString("personId")).put("name",p.getString("name")).put("amount",left).put("collectable",p.getLong("amount")-reserved.getOrDefault(key,0L)).put("loan",p.getBoolean("loan")).put("prior",true).put("note",p.optString("note")).put("date",p.optString("date")).put("due",""));}JSONArray tx=d.getJSONArray("transactions");for(int i=0;i<tx.length();i++){JSONObject t=tx.getJSONObject(i);if(!Arrays.asList("expense","loan").contains(t.optString("type"))||!t.optString("status").equals("posted")||t.getString("date").compareTo(Ledger.today())>0)continue;JSONArray parts=t.optJSONArray("shares");if(parts==null)continue;for(int j=0;j<parts.length();j++){JSONObject s=parts.getJSONObject(j);String key=t.getString("id")+":"+s.getString("id");long left=s.getLong("amount")-posted.getOrDefault(key,0L);if(left>0||includeClosed)out.put(new JSONObject().put("key",key).put("personId",s.optString("personId")).put("name",s.optString("name")).put("amount",left).put("collectable",s.getLong("amount")-reserved.getOrDefault(key,0L)).put("loan",t.optString("type").equals("loan")).put("note",t.optString("note")).put("date",t.optString("date")).put("due",t.optString("due")));}}return out;}
 static boolean belongs(JSONObject claim,JSONObject person){return claim.optString("personId").equals(person.optString("id"))||claim.optString("personId").isEmpty()&&BankNotificationParser.normalize(claim.optString("name")).equals(BankNotificationParser.normalize(person.optString("name")));}
 static long owed(JSONObject d,String kind,JSONObject person)throws Exception{return owed(claims(d),kind,person);}
 static long owed(JSONArray claims,String kind,JSONObject person)throws Exception{long total=0;for(int i=0;i<claims.length();i++){JSONObject c=claims.getJSONObject(i);if((kind.isEmpty()||c.optBoolean("loan")==kind.equals("loan"))&&(person==null||belongs(c,person)))total+=c.getLong("amount");}return total;}
 static Map<String,Long> paymentsIndex(JSONObject d,boolean reserved)throws Exception{Map<String,Long> result=new HashMap<>();JSONArray debts=d.getJSONArray("receivables");for(int i=0;i<debts.length();i++){JSONObject p=debts.getJSONObject(i);result.put("prior:"+p.getString("id"),p.optLong("settled"));}JSONArray tx=d.getJSONArray("transactions");String today=Ledger.today();for(int i=0;i<tx.length();i++){JSONObject t=tx.getJSONObject(i);if(t.optString("type").equals("repayment")&&(reserved||t.optString("status").equals("posted")&&t.optString("date").compareTo(today)<=0)){String key=t.optString("receivable");result.put(key,Math.addExact(result.getOrDefault(key,0L),t.getLong("amount")));}}return result;}
 static JSONObject claim(JSONObject d,String key)throws Exception{JSONArray claims=claims(d);for(int i=0;i<claims.length();i++)if(claims.getJSONObject(i).getString("key").equals(key))return claims.getJSONObject(i);return null;}
 static JSONObject priorDraft(JSONObject person)throws Exception{JSONObject debt=new JSONObject().put("id",Ledger.id()).put("settled",0);if(person!=null)debt.put("personId",person.getString("id")).put("name",person.getString("name"));return debt;}
 /** Reclassifies an existing credit; account and total balance remain unchanged. */
 static void linkIncome(JSONObject d,String transactionId,String claimKey)throws Exception{
  JSONObject t=Ledger.find(d.getJSONArray("transactions"),transactionId),claim=claim(d,claimKey);
  Ledger.require(t!=null&&t.optString("type").equals("income")&&t.optString("status").equals("posted")&&!t.optBoolean("excluded")&&t.getString("date").compareTo(Ledger.today())<=0,"Selecciona un ingreso confirmado");
  Ledger.require(claim!=null&&claim.optLong("collectable")>0,"Esa deuda ya está saldada");
  long original=t.getLong("amount"),applied=Math.min(original,claim.getLong("collectable"));Ledger.require(applied>0,"Monto inválido");
  if(original>applied){JSONObject rest=new JSONObject(t.toString()).put("id",Ledger.id()).put("amount",original-applied).put("source","manual").put("sourceId","").put("note",t.optString("note")+" · resto").put("relatedReceivable",claimKey).put("relatedRepayment",t.getString("id"));d.getJSONArray("transactions").put(rest);}
  t.put("linkedIncomeCategory",t.optString("category")).put("type","repayment").put("amount",applied).put("category","").put("receivable",claimKey);
 }
 static void unlinkIncome(JSONObject d,String transactionId)throws Exception{JSONObject t=Ledger.find(d.getJSONArray("transactions"),transactionId);Ledger.require(t!=null&&t.optString("type").equals("repayment")&&t.has("linkedIncomeCategory"),"Este cobro no proviene de un ingreso vinculado");String category=t.getString("linkedIncomeCategory");Ledger.require(Ledger.find(d.getJSONArray("categories"),category)!=null,"La categoría original ya no existe");t.put("type","income").put("category",category).put("receivable","");t.remove("linkedIncomeCategory");}
 /** Closes a pre-app debt without posting a second bank movement. */
 static void settlePrior(JSONObject d,String claimKey)throws Exception{JSONObject claim=claim(d,claimKey);Ledger.require(claim!=null,"La deuda ya está saldada");abonoPrior(d,claimKey,claim.getLong("collectable"));}
  static void abonoPrior(JSONObject d,String claimKey,long amount)throws Exception{abonoPrior(d,claimKey,amount,Ledger.today(),"");}
  static void abonoPrior(JSONObject d,String claimKey,long amount,String date,String note)throws Exception{abonoPrior(d,claimKey,amount,date,note,"Regalo");}
  static void abonoPrior(JSONObject d,String claimKey,long amount,String date,String note,String extraKind)throws Exception{Ledger.require(claimKey.startsWith("prior:"),"Solo las deudas anteriores admiten abonos sin movimiento");JSONObject claim=claim(d,claimKey),prior=Ledger.find(d.getJSONArray("receivables"),claimKey.substring(6));Ledger.require(claim!=null&&prior!=null&&amount>0,"Monto inválido");LocalDate.parse(date);Ledger.require(note.length()<=300,"Nota demasiado larga");long principal=Math.min(amount,claim.optLong("collectable")),extra=amount-principal;prior.put("settled",prior.getLong("settled")+principal);JSONArray history=prior.optJSONArray("settlementHistory");if(history==null){history=new JSONArray();prior.put("settlementHistory",history);}history.put(new JSONObject().put("id",Ledger.id()).put("date",date).put("amount",principal).put("extra",extra).put("extraKind",extraKind).put("note",note).put("createdAt",System.currentTimeMillis()));}
  static void reopenPrior(JSONObject d,String id)throws Exception{JSONObject prior=Ledger.find(d.getJSONArray("receivables"),id);Ledger.require(prior!=null&&prior.optLong("settled")>0,"No hay un cierre manual que reabrir");prior.put("settled",0);JSONArray history=prior.optJSONArray("settlementHistory");if(history!=null)for(int i=0;i<history.length();i++){JSONObject entry=history.getJSONObject(i);if(!entry.optBoolean("voided"))entry.put("voided",true).put("voidedAt",System.currentTimeMillis());}}
 static long planned(JSONObject d,String through)throws Exception{long total=0;JSONArray plans=d.getJSONArray("planned"),txs=d.getJSONArray("transactions");for(int i=0;i<plans.length();i++){JSONObject p=plans.getJSONObject(i);if(p.optString("status").equals("planned")&&p.getString("date").compareTo(through)<=0)total+=p.getLong("amount");}for(int i=0;i<txs.length();i++){JSONObject t=txs.getJSONObject(i);if(t.optString("type").equals("expense")&&t.optString("status").equals("posted")&&t.getString("date").compareTo(Ledger.today())>0&&t.getString("date").compareTo(through)<=0){JSONObject account=Ledger.find(d.getJSONArray("accounts"),t.optString("account"));if(!account.optString("type").equals("credit")||t.optInt("installments",1)==1)total+=t.getLong("amount");}}JSONArray rs=d.getJSONArray("recurring");for(int i=0;i<rs.length();i++){JSONObject r=rs.getJSONObject(i);if(!r.optBoolean("active")||!r.optString("type").equals("expense"))continue;String date=r.getString("next");int n=0;while(date.compareTo(through)<=0&&n++<120){if(Ledger.find(txs,"auto-"+r.getString("id")+"-"+date)==null)total+=r.getLong("amount");date=Ledger.next(date,r.getString("frequency"),r.optInt("anchorDay"));}}return total;}
 static void payPlan(JSONObject d,String id)throws Exception{JSONObject p=Ledger.find(d.getJSONArray("planned"),id);Ledger.require(p!=null&&p.optString("status").equals("planned"),"El previsto ya se pagó o canceló");JSONObject t=NativeSync.transaction("expense",p.getLong("amount"),p.getString("account"),"",p.getString("category"),p.getString("name"),"manual","");t.put("plannedId",id);d.getJSONArray("transactions").put(t);p.put("status","paid").put("transactionId",t.getString("id"));}
}



